from mk import *
from lib import fbd
STRICT["on"] = True

def fig():
    g = Fig(560, 300, "גרף מהירות-זמן: 500 מטר לשנייה עד 0.02 שניות, ירידה קווית ל-100 מטר לשנייה ב-0.022 שניות, ואחר כך קבועה")
    X, Y = g.graph(70, 250, 420, 200, "t (s)", "v (m/s)", xticks=[(0.01, "0.01"), (0.02, "0.02"), (0.03, "0.03")],
                   yticks=[(100, "100"), (200, "200"), (300, "300"), (400, "400"), (500, "500")], xmax=0.03, ymax=500)
    g.plot(X, Y, [(0, 500), (0.02, 500), (0.022, 100), (0.03, 100)])
    g.line(X(0.02), Y(500), X(0.02), Y(0), stroke="var(--d-dim)", width=1, dash="4 3")
    g.line(X(0.022), Y(100), X(0.022), Y(0), stroke="var(--d-dim)", width=1, dash="4 3")
    g.text(X(0.022) + 4, Y(0) - 6, "0.022", cls="dim", anchor="start")
    return g

E(id="bagrut-1980w-q2", year=1980, label="1980 חורף שאלה 2", topic="kinematics", sub="kin-graphs", diff=2, fig=fig,
  stem=r"הגרף מתאר את מהירותו של גוף כפונקציה של הזמן. מסת הגוף $20$ גרם.",
  parts=[
    P("א", r"המציאו בעיה מציאותית שמתאימה לגרף, כולל המספרים שבו.", OPEN, ["understanding", "graph"], [
        X(r"אין תשובה אחת נכונה. בעיה טובה צריכה להסביר את שלושת השלבים שבגרף: מהירות קבועה גבוהה, האטה חדה מאוד בזמן קצר מאוד, ושוב מהירות קבועה, נמוכה יותר."),
        S(r"קוראים את השלבים מהגרף", r"כל קטע ישר בגרף מהירות-זמן הוא שלב עם תאוצה קבועה. קטע אופקי פירושו מהירות קבועה", r"500\,\tfrac{\text{m}}{\text{s}} \;\xrightarrow{\;0.002\,\text{s}\;}\; 100\,\tfrac{\text{m}}{\text{s}}"),
        S(r"מציעים סיפור: קליע שעובר דרך לוח עץ", r"מהירות כזו ומסה של עשרים גרם מתאימות לקליע. האטה בשתי אלפיות שנייה מתאימה למעבר דרך לוח", r"m = 20\,\text{g},\quad v_0 = 500\,\tfrac{\text{m}}{\text{s}}"),
        S(r"בודקים שהמספרים מתאימים", r"בזמן המעבר הקליע עובר מרחק ששווה לשטח שמתחת לגרף בשלב השני. זה עובי הלוח בסיפור שלנו. השטח הוא טרפז", r"\Delta x = \frac{500 + 100}{2} \cdot 0.002 = 0.6\,\text{m}", eq=r"x = x_0 + \frac{v_0 + v}{2}\,t"),
    ], r"למשל: קליע של $20$ גרם שנע ב-$500\,\text{m/s}$ חודר לוח בעובי $0.6\,\text{m}$ ויוצא ממנו ב-$100\,\text{m/s}$"),
    P("ב", r"חשבו את גודל הכוח השקול שפועל על הגוף בכל אחד משלבי התנועה.", multi((r"שלב ראשון, עד $0.02\,\text{s}$", 0, "N"), (r"שלב שני, מ-$0.02$ עד $0.022\,\text{s}$", 4000, "N"), (r"שלב שלישי, אחרי $0.022\,\text{s}$", 0, "N")), ["graph", "fbd", "signs", "principle", "units"], [
        X(r"הכוח השקול נקבע לפי התאוצה (החוק השני של ניוטון), והתאוצה היא השיפוע של גרף מהירות-זמן. לכן בודקים את השיפוע בכל שלב. הכיוון החיובי נקבע לפי הגרף: המהירות חיובית כל הזמן, ולכן כיוון התנועה הוא הכיוון החיובי."),
        D(r"תרשים הכוחות בשלב השני (רק בציר התנועה)", lambda: fbd([("F", 180, 1.2)], "תרשים כוחות של הקליע בשלב השני: כוח F נגד כיוון התנועה. הכיוון החיובי בכיוון התנועה", positive=0, body="ball", note="הגוף מאט")),
        S(r"שלב ראשון", r"הגרף אופקי, ולכן השיפוע אפס. אין תאוצה, ולכן הכוח השקול אפס", r"a_1 = 0 \;\Rightarrow\; F_1 = m \cdot 0 = 0", eq=r"\Sigma\vec F = m\vec a"),
        S(r"שלב שני: התאוצה", r"השיפוע הוא השינוי במהירות חלקי משך השלב. המהירות יורדת, ולכן התאוצה שלילית, כלומר נגד הכיוון החיובי", r"a_2 = \frac{100 - 500}{0.022 - 0.02} = \frac{-400}{0.002} = -2 \times 10^{5}\,\text{m/s}^2", eq=r"\bar a = \frac{\Delta v}{\Delta t}"),
        S(r"ממירים את המסה לקילוגרם", r"היחידה ניוטון מוגדרת עם קילוגרם", r"m = 20\,\text{g} = 0.02\,\text{kg}"),
        S(r"משוואת כוחות בשלב השני", r"בכיוון החיובי לא פועל אף כוח. נגד הכיוון החיובי פועל הכוח שמאט את הגוף. לכן באגף שמאל יש רק את הכוח הזה, עם סימן מינוס", r"0 - F_2 = m a_2", eq=r"\Sigma\vec F = m\vec a"),
        S(r"מציבים ופותרים", r"מציבים את המסה ואת התאוצה, ומכפילים את שני האגפים במינוס אחת", r"-F_2 = 0.02 \cdot (-2 \times 10^{5}) = -4000 \;\Rightarrow\; F_2 = 4000\,\text{N}"),
        S(r"שלב שלישי", r"שוב קטע אופקי בגרף: אין תאוצה, ולכן הכוח השקול אפס", r"a_3 = 0 \;\Rightarrow\; F_3 = 0"),
        C(r"בדיקה בדרך אחרת: מתקף מול שינוי תנע", r"המתקף של הכוח השקול שווה לשינוי בתנע", r"-F_2\,\Delta t = -4000 \cdot 0.002 = -8 \quad;\quad m\,\Delta v = 0.02 \cdot (-400) = -8 \;\checkmark", eq=r"\vec J_{\text{tot}} = \Delta\vec p"),
    ], r"בשלב הראשון ובשלב השלישי הכוח השקול $0$. בשלב השני $F = 4000\,\text{N}$, נגד כיוון התנועה", key=r"0<t<0.02: F=0 ; 0.02<t<0.022: F=4×10^3 N נגד כיוון התנועה ; t>0.022: F=0"),
  ],
  concepts=["גרף מהירות-זמן", "שיפוע כתאוצה", "החוק השני של ניוטון", "שטח מתחת לגרף כהעתק"],
  summary=r"קריאת שלבי תנועה מגרף מהירות-זמן, ומעבר משיפוע לתאוצה ולכוח השקול.",
  review="הנחה שלי.\nסעיף א פתוח: הצעתי סיפור של קליע ולוח.\nסעיף ב הוא סעיף אחד, כמו במקור, עם שלוש תיבות (כוח בכל שלב).\nמה לבדוק: את הסיפור בסעיף א.")
